create table if not exists public.mi_asset_type_map (
  raw_type   text primary key,
  base_class text not null check (base_class in ('sfr', 'mf_generic', 'mf_5_plus', 'land', 'other_res', 'commercial', 'unknown'))
);
-- The 7 raw values in the corpus (audited 2026-10-04). A value not in this table is 'unknown'
-- (the JS resolver's verdict for an unrecognised label) and is listed on the build (notes.unmapped_types).
insert into public.mi_asset_type_map (raw_type, base_class) values
  ('Single Family', 'sfr'),
  ('Vacant Land', 'land'),
  ('Other', 'unknown'),
  ('Multi-Family', 'mf_generic'),
  ('Apartment', 'mf_5_plus'),
  ('Townhouse', 'other_res'),
  ('Mobile Home', 'other_res')
on conflict (raw_type) do nothing;

create table if not exists public.mi_rollup_builds (
  build_id        bigint generated always as identity primary key,
  status          text not null default 'building' check (status in ('building', 'ready', 'superseded', 'failed')),
  fingerprint     jsonb not null,
  source_as_of    date not null,
  source_first    date,
  source_rows     bigint not null,
  units           text[] not null,
  cursor          integer not null default 0,
  attempts        integer not null default 0,
  ticks           integer not null default 0,
  rows_written    bigint not null default 0,
  db_ms           bigint not null default 0,
  last_unit       text,
  last_unit_ms    integer,
  last_error      text,
  notes           jsonb not null default '{}'::jsonb,
  started_at      timestamptz not null default now(),
  ready_at        timestamptz,
  finished_at     timestamptz,
  updated_at      timestamptz not null default now()
);
create unique index if not exists mi_rollup_builds_one_building on public.mi_rollup_builds ((true)) where status = 'building';
create index if not exists mi_rollup_builds_ready on public.mi_rollup_builds (build_id desc) where status = 'ready';

create table if not exists public.mi_rollup_sync_state (
  key               text primary key,
  last_run_at       timestamptz,
  last_checked_at   timestamptz,
  last_result       text,
  last_skip_reason  text,
  last_ms           integer,
  updated_at        timestamptz not null default now()
);
insert into public.mi_rollup_sync_state (key) values ('nightly') on conflict (key) do nothing;

create table if not exists public.mi_zip_geo (
  build_id    bigint not null references public.mi_rollup_builds (build_id) on delete cascade,
  zip         text not null,
  state       text,
  city_key    text,
  county_key  text,
  county_name text,
  county_via  text check (county_via in ('census', 'parcel_majority')),
  market_key  text,
  sales_n     integer not null default 0,
  min_lat double precision, max_lat double precision, min_lng double precision, max_lng double precision,
  primary key (build_id, zip)
);

create table if not exists public.mi_geo_period_rollup (
  build_id      bigint not null references public.mi_rollup_builds (build_id) on delete cascade,
  geo_level     text not null,
  geo_key       text not null,
  period        text not null,
  asset         text not null,
  sale_count            integer not null,
  priced_sale_count     integer not null,
  qualified_sale_count  integer not null,
  mls_count             integer not null,
  mf_sale_count         integer not null,
  investor_count        integer not null,
  buyer_known_count     integer not null,
  cash_known_count      integer not null,
  cash_count            integer not null,
  entity_owned_count    integer not null,
  latest_sale           date,
  median_price double precision, median_ppsf double precision, ppsf_n integer not null,
  median_ppu double precision, ppu_n integer not null,
  median_inv_price double precision, inv_price_n integer not null,
  price_deciles double precision[],
  n_sfr integer not null, n_mf_2_4 integer not null, n_mf_5_plus integer not null, n_mf_unknown integer not null,
  n_land integer not null, n_commercial integer not null, n_other_res integer not null, n_unknown integer not null,
  u_2 integer not null, u_3 integer not null, u_4 integer not null, u_5_9 integer not null, u_10_19 integer not null,
  u_20_49 integer not null, u_50p integer not null, u_unrec integer not null,
  s_lt2k integer not null, s_2_4k integer not null, s_4_8k integer not null, s_8_20k integer not null, s_20kp integer not null, s_unrec integer not null,
  primary key (build_id, geo_level, period, asset, geo_key)
